public sealed record IconDefinition(string SourceName, string Style, string Data16, string Data24)
{
    public static int CanvasFor(double display) => display <= 20 ? 16 : 24;

    public Geometry CreateGeometry(double display)
    {
        var canvas = CanvasFor(display);
        var geometry = FluentPath.Parse(canvas == 16 ? Data16 : Data24);
        geometry.Transform = new ScaleTransform { ScaleX = display / canvas, ScaleY = display / canvas };
        return geometry;
    }
}
